using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;
public class ValidateTraderBounty085 {
 static void Capture(Transform h,Vector3 p,Vector3 target,string file,float fov){var go=new GameObject("Temporary_Trader_Bounty_Camera");var rt=new RenderTexture(1600,1100,24);var tex=new Texture2D(1600,1100,TextureFormat.RGB24,false);var prev=RenderTexture.active;try{var cam=go.AddComponent<Camera>();cam.transform.position=h.TransformPoint(p);cam.transform.LookAt(h.TransformPoint(target));cam.fieldOfView=fov;cam.farClipPlane=120;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1600,1100),0,0);tex.Apply();File.WriteAllBytes("Docs/assets/examples/"+file+".png",tex.EncodeToPNG());}finally{RenderTexture.active=prev;UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}}
 public static string Main(){if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new Exception("Unsaved owner edits");EditorSceneManager.OpenScene("Assets/Scenes/CastleServicesWorkshop.unity",OpenSceneMode.Single);var hs=GameObject.Find("Castle_Services_Prototype").transform.Find("03_Service_Houses");var sh=hs.Find("05_Nursery");var tr=hs.Find("03_LootTrader");var board=sh.Find("22_Original_Bounty_Board");var source=sh.Find("15_Gameplay_Source").GetComponentsInChildren<Transform>(true).First(t=>t.name=="SheriffDesk");var texts=board.Find("Canvas").GetComponentsInChildren<Text>(true);if(!texts.Select(t=>t.text).SequenceEqual(source.Find("Canvas").GetComponentsInChildren<Text>(true).Select(t=>t.text)))throw new Exception("Bounty amounts changed");if(!board.Find("Canvas").GetComponentsInChildren<Image>(true).Select(i=>i.sprite).SequenceEqual(source.Find("Canvas").GetComponentsInChildren<Image>(true).Select(i=>i.sprite)))throw new Exception("Bounty icons changed");foreach(var t in tr.Find("22_Trader_Detail").GetComponentsInChildren<Transform>())if(t.name=="Material_Roll"){var p=t.localPosition;p.y=1.82f;t.localPosition=p;}
 var sell=tr.Find("15_Gameplay_Source/SellPoint");var col=sell.GetComponent<BoxCollider>();var money=sell.GetComponentsInChildren<Transform>(true).First(t=>t.name=="MoneyBagPoint");var rugs=tr.Find("23_Trader_Service_Mats");var reward=rugs.Find("Trade_Reward_Rug");if(Vector3.Distance(tr.InverseTransformPoint(money.position),reward.localPosition+Vector3.up*.01f)>.001f)throw new Exception("Reward misaligned");Physics.SyncTransforms();if(!Physics.OverlapBox(tr.TransformPoint(rugs.Find("Finds_Delivery_Rug").localPosition+Vector3.up*.35f),new Vector3(.1f,.2f,.1f),tr.rotation,~0,QueryTriggerInteraction.Collide).Contains(col))throw new Exception("Intake misaligned");
 string paths="";var probe=new GameObject("Temporary_Trader_Approach");try{var cc=probe.AddComponent<CharacterController>();cc.height=1.8f;cc.radius=.35f;cc.center=new Vector3(0,.9f,0);cc.stepOffset=.3f;foreach(Transform rug in rugs){var target=rug.localPosition;probe.transform.position=tr.TransformPoint(new Vector3(0,.55f,-4.5f));Physics.SyncTransforms();for(int j=0;j<105;j++){var p=tr.InverseTransformPoint(probe.transform.position);if(p.z>=target.z-.02f)break;cc.Move(tr.TransformVector(new Vector3(0,0,.04f))+Vector3.down*.025f);}for(int j=0;j<70;j++){var p=tr.InverseTransformPoint(probe.transform.position);float d=target.x-p.x;if(Mathf.Abs(d)<.02f)break;cc.Move(tr.TransformVector(new Vector3(Mathf.Clamp(d,-.04f,.04f),0,0))+Vector3.down*.025f);}var end=tr.InverseTransformPoint(probe.transform.position);if(Vector2.Distance(new Vector2(end.x,end.z),new Vector2(target.x,target.z))>.15f||!cc.isGrounded)throw new Exception("Approach blocked "+end);paths+=end+"; ";}}finally{UnityEngine.Object.DestroyImmediate(probe);}
 if(tr.GetComponentsInChildren<TextMesh>(true).Length!=0||sh.GetComponentsInChildren<TextMesh>(true).Length!=0)throw new Exception("Non UI label");Capture(tr,new Vector3(0,2.35f,-2.65f),new Vector3(0,1.3f,1.7f),"Trader_Find_Delivery_Interior",101);Capture(sh,new Vector3(6,3.5f,-9),new Vector3(1.25f,1.6f,-3.3f),"Sheriff_Original_Bounty_Board",65);EditorSceneManager.MarkSceneDirty(tr.gameObject.scene);EditorSceneManager.SaveScene(tr.gameObject.scene);string report="PASS: duplicated inherited SheriffDesk prices/icons preserved; localized UI header; original gameplay configuration retained; item intake rug contacts SellPoint; reward point aligned; player approaches both rugs "+paths+"; no TextMesh; scene saved. Full sale/reward gameplay untested (Fusion unavailable).";File.WriteAllText("Docs/assets/examples/TRADER_BOUNTY085_VALIDATION.txt",report+"\n");return report;}}
